const request = $json ?? {};
const body = (request && typeof request === 'object' && request.body && typeof request.body === 'object') ? request.body : request;
const env = $env ?? {};

function trimSlash(v) {
  return String(v || '').replace(/\/+$/, '');
}

function pickEnv(...keys) {
  for (const k of keys) {
    const v = env?.[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v);
  }
  return '';
}

function pickBody(...keys) {
  for (const k of keys) {
    const v = body?.[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v);
  }
  return '';
}

function isTruthy(v) {
  const raw = String(v ?? '').trim().toLowerCase();
  return ['1', 'true', 'yes', 'y', 'on'].includes(raw);
}

function normalizeIssuesInput() {
  const issues = Array.isArray(body?.issues) ? body.issues : [];
  const out = [];

  function pushIssue(issue) {
    if (!issue || typeof issue !== 'object') return;
    const iid = issue.iid ?? issue.issue_iid ?? issue.issueIid ?? null;
    const webUrl = issue.web_url ?? issue.webUrl ?? issue.url ?? null;
    const projectRef = issue.project_ref ?? issue.projectRef ?? issue.project_path ?? issue.projectPath ?? null;
    const title = issue.title ?? null;
    const usecaseIds = Array.isArray(issue.usecase_ids) ? issue.usecase_ids : [];
    out.push({ iid, web_url: webUrl, project_ref: projectRef, title, usecase_ids: usecaseIds });
  }

  for (const issue of issues) pushIssue(issue);

  const singleIid = pickBody('issue_iid', 'iid');
  const singleUrl = pickBody('issue_web_url', 'issue_url', 'web_url');
  const singleProject = pickBody('project_ref', 'project_path', 'gitlab_project_path');
  if (out.length == 0 && (singleIid || singleUrl)) {
    out.push({ iid: singleIid || null, web_url: singleUrl || null, project_ref: singleProject || null, title: null, usecase_ids: [] });
  }

  return out;
}

function parseIssueUrl(url) {
  const raw = String(url || '').trim();
  if (!raw) return null;
  const m = raw.match(/https?:\/\/[^/]+\/(?<project>.+?)\/-\/issues\/(?<iid>\d+)/);
  if (!m || !m.groups) return null;
  return { project_ref: m.groups.project, iid: m.groups.iid };
}

const realm = String(
  pickBody('realm', 'N8N_REALM') ||
  pickEnv('N8N_REALM') ||
  pickEnv('N8N_OBSERVER_REALM') ||
  'default'
).trim() || 'default';

const gitlabBaseUrl = trimSlash(
  pickBody('gitlab_base_url', 'GITLAB_BASE_URL', 'N8N_GITLAB_BASE_URL') ||
  pickEnv('N8N_GITLAB_BASE_URL', 'GITLAB_BASE_URL', 'GITLAB_URL', 'SERVICE_URL_GITLAB')
);

let gitlabApiBaseUrl = trimSlash(
  pickBody('gitlab_api_base_url', 'GITLAB_API_BASE_URL', 'N8N_GITLAB_API_BASE_URL') ||
  pickEnv('N8N_GITLAB_API_BASE_URL', 'GITLAB_API_BASE_URL') ||
  (gitlabBaseUrl ? `${gitlabBaseUrl}/api/v4` : '')
);

const gitlabToken = String(
  pickEnv('N8N_GITLAB_TOKEN', 'GITLAB_TOKEN', 'GITLAB_ADMIN_TOKEN') ||
  ''
).trim();


const groupFullPath = pickBody('gitlab_group_full_path') || pickEnv('N8N_GITLAB_GROUP_FULL_PATH', 'GITLAB_GROUP_FULL_PATH', 'GROUP_FULL_PATH');
const defaultProjectPath = groupFullPath ? `${groupFullPath}/general-management` : `${realm}/general-management`;

const projectRef = (
  pickBody('gitlab_project_id', 'gitlab_project_path', 'GITLAB_PROJECT_ID', 'GITLAB_PROJECT_PATH') ||
  pickEnv('N8N_GITLAB_GENERAL_MANAGEMENT_PROJECT_ID', 'GITLAB_GENERAL_MANAGEMENT_PROJECT_ID') ||
  pickEnv('N8N_GITLAB_GENERAL_MANAGEMENT_PROJECT_PATH', 'GITLAB_GENERAL_MANAGEMENT_PROJECT_PATH') ||
  pickBody('N8N_GITLAB_PROJECT_ID', 'N8N_GITLAB_PROJECT_PATH') ||
  pickEnv('N8N_GITLAB_PROJECT_ID', 'GITLAB_PROJECT_ID', 'N8N_GITLAB_PROJECT_PATH', 'GITLAB_PROJECT_PATH') ||
  defaultProjectPath
);

const cirLabel = String(pickBody('cir_label') || pickEnv('ITSM_CIR_LABEL') || 'ITSM/継続的改善').trim() || 'ITSM/継続的改善';
const closedLabel = String(pickBody('closed_label', 'status_label') || pickEnv('ITSM_CIR_CLOSED_LABEL') || '状態/Closed').trim() || '状態/Closed';
const statusPrefix = String(pickBody('status_prefix') || pickEnv('ITSM_CIR_STATUS_PREFIX') || '状態/').trim() || '状態/';

const dryRun = isTruthy(pickBody('dry_run') || pickEnv('ITSM_CIR_CLOSE_DRY_RUN') || pickEnv('DRY_RUN') || 'false');
const closeState = (pickBody('close_state') === '') ? true : (pickBody('close_state') ? isTruthy(pickBody('close_state')) : true);
const appendNote = (pickBody('append_note') === '') ? true : (pickBody('append_note') ? isTruthy(pickBody('append_note')) : true);
const forceNote = isTruthy(pickBody('force_note') || pickEnv('ITSM_CIR_CLOSE_FORCE_NOTE') || 'false');

const targetAppRoot = String(pickBody('target_app_root') || '').trim() || null;
const resultSummary = body?.result_summary !== undefined ? String(body.result_summary) : (body?.summary !== undefined ? String(body.summary) : '');
const artifacts = Array.isArray(body?.artifacts) ? body.artifacts : [];
const verification = body?.verification && typeof body.verification === 'object' ? body.verification : null;
const runMeta = body?.run_meta && typeof body.run_meta === 'object' ? body.run_meta : null;

const issuesIn = normalizeIssuesInput();
const normalizedIssues = [];
for (const raw of issuesIn) {
  const parsed = raw.web_url ? parseIssueUrl(raw.web_url) : null;
  const iid = raw.iid || (parsed ? parsed.iid : null);
  const pref = raw.project_ref || (parsed ? parsed.project_ref : null) || projectRef;
  normalizedIssues.push({
    iid: iid ? String(iid).trim() : '',
    project_ref: pref ? String(pref).trim() : '',
    web_url: raw.web_url ? String(raw.web_url).trim() : (parsed ? String(raw.web_url || '').trim() : ''),
    title: raw.title ? String(raw.title) : null,
    usecase_ids: Array.isArray(raw.usecase_ids) ? raw.usecase_ids : [],
  });
}

const missing = [];
if (!gitlabApiBaseUrl) missing.push('GITLAB_API_BASE_URL');
if (!gitlabToken) missing.push('GITLAB_TOKEN');
if (!projectRef) missing.push('GITLAB_GENERAL_MANAGEMENT_PROJECT_(ID|PATH)');

if (!dryRun && missing.length) {
  return [{
    json: {
      ok: false,
      status_code: 424,
      error: 'missing_gitlab_config',
      missing,
      realm,
      issues: normalizedIssues,
    }
  }];
}

// emit one item per issue
if (normalizedIssues.length === 0) {
  return [{
    json: {
      ok: true,
      status_code: 200,
      skipped: true,
      reason: 'no_issues',
      realm,
      dry_run: dryRun,
      gitlab_api_base_url: gitlabApiBaseUrl,
      project_ref: projectRef,
      issues: [],
    }
  }];
}

return normalizedIssues.map((issue) => ({
  json: {
    ok: true,
    realm,
    dry_run: dryRun,
    gitlab_api_base_url: gitlabApiBaseUrl,
    project_ref: issue.project_ref || projectRef,
    issue_iid: issue.iid,
    issue_web_url: issue.web_url || null,
    issue_title_hint: issue.title || null,
    usecase_ids: issue.usecase_ids || [],
    cir_label: cirLabel,
    closed_label: closedLabel,
    status_prefix: statusPrefix,
    close_state: closeState,
    append_note: appendNote,
    force_note: forceNote,
    target_app_root: targetAppRoot,
    result_summary: resultSummary,
    artifacts,
    verification,
    run_meta: runMeta,
    missing,
  }
}));

const req = $json ?? {};
const env = $env || {};


function isNumeric(v) {
  return typeof v === 'number' || (typeof v === 'string' && /^[0-9]+$/.test(v));
}

function encProjectRef(ref) {
  const r = String(ref ?? '').trim();
  return isNumeric(r) ? r : encodeURIComponent(r);
}

function safeString(v) {
  const s = (v === undefined || v === null) ? '' : String(v);
  return s;
}

function normalizeLabels(labelsRaw) {
  const labels = Array.isArray(labelsRaw) ? labelsRaw : [];
  const out = [];
  for (const l of labels) {
    if (l === null || l === undefined) continue;
    if (typeof l === 'string') {
      const t = l.trim();
      if (t) out.push(t);
    } else if (typeof l === 'object') {
      const t = String(l.title ?? l.name ?? '').trim();
      if (t) out.push(t);
    }
  }
  return out;
}

function uniq(list) {
  const out = [];
  const seen = new Set();
  for (const v of list || []) {
    const s = String(v ?? '').trim();
    if (!s) continue;
    if (seen.has(s)) continue;
    seen.add(s);
    out.push(s);
  }
  return out;
}

function buildNoteBody(params) {
  const NL = String.fromCharCode(10);
  const now = new Date().toISOString();
  const marker = params.marker;
  const lines = [];
  lines.push(marker);
  lines.push('### 自動クローズ（system.md）');
  lines.push(`- closed_at: ${now}`);
  if (params.target_app_root) lines.push(`- target_app_root: ${params.target_app_root}`);
  if (params.operator) lines.push(`- operator: ${params.operator}`);
  if (params.run_id) lines.push(`- run_id: ${params.run_id}`);
  if (params.status_label) lines.push(`- status: ${params.status_label}`);
  if (params.issue_url) lines.push(`- issue: ${params.issue_url}`);

  if (params.usecase_ids && params.usecase_ids.length) {
    lines.push('');
    lines.push('#### Usecases');
    for (const id of params.usecase_ids) lines.push(`- ${id}`);
  }

  if (params.result_summary) {
    lines.push('');
    lines.push('#### Result Summary');
    lines.push(String(params.result_summary).trim());
  }

  if (params.verification) {
    lines.push('');
    lines.push('#### Verification');
    try {
      lines.push('```json');
      lines.push(JSON.stringify(params.verification, null, 2));
      lines.push('```');
    } catch (e) {}
  }

  const artifacts = Array.isArray(params.artifacts) ? params.artifacts : [];
  if (artifacts.length) {
    lines.push('');
    lines.push('#### Artifacts');
    for (const a of artifacts) {
      const t = (a && typeof a === 'object')
        ? (a.url ? `${a.name || 'artifact'}: ${a.url}` : JSON.stringify(a))
        : String(a);
      lines.push(`- ${t}`);
    }
  }

  lines.push('');
  lines.push('（このコメントは自動生成です）');

  return lines.join(NL);
}

const dryRun = Boolean(req.dry_run);
const apiBase = safeString(req.gitlab_api_base_url).replace(/\/+$/, '');
const token = safeString(env.N8N_GITLAB_TOKEN || env.GITLAB_TOKEN || env.GITLAB_ADMIN_TOKEN || '');
const projectRef = safeString(req.project_ref);
const iid = safeString(req.issue_iid);
const cirLabel = safeString(req.cir_label || 'ITSM/継続的改善');
const closedLabel = safeString(req.closed_label || '状態/Closed');
const statusPrefix = safeString(req.status_prefix || '状態/');
const closeState = req.close_state !== false;
const appendNote = req.append_note !== false;
const forceNote = Boolean(req.force_note);

if (!iid || !projectRef) {
  return { json: { ...req, ok: false, status_code: 400, error: 'issue_iid and project_ref are required' } };
}

const encodedProject = encProjectRef(projectRef);
const issueUrl = `${apiBase}/projects/${encodedProject}/issues/${encodeURIComponent(iid)}`;

if (dryRun) {
  const marker = `<!-- itsm:cir:close:project=${projectRef} iid=${iid} status=${closedLabel} -->`;
  const noteBody = buildNoteBody({
    marker,
    target_app_root: req.target_app_root,
    operator: req.run_meta?.operator || null,
    run_id: req.run_meta?.run_id || null,
    status_label: closedLabel,
    issue_url: req.issue_web_url || null,
    usecase_ids: Array.isArray(req.usecase_ids) ? req.usecase_ids : [],
    result_summary: req.result_summary,
    verification: req.verification,
    artifacts: req.artifacts,
  });

  return {
    json: {
      ...req,
      ok: true,
      dry_run: true,
      planned: {
        get_issue: issueUrl,
        update_issue: closeState ? { method: 'PUT', url: issueUrl, add_labels: closedLabel, remove_status_prefix: statusPrefix, state_event: 'close' } : null,
        add_note: appendNote ? { method: 'POST', url: `${issueUrl}/notes`, marker } : null,
      },
      note_preview: noteBody,
    }
  };
}

// GET issue
let issue;
try {
  issue = await this.helpers.httpRequest({
    method: 'GET',
    url: issueUrl,
    json: true,
    headers: { 'PRIVATE-TOKEN': token },
    timeout: 8000,
  });
} catch (error) {
  return { json: { ...req, ok: false, status_code: 502, error: 'gitlab_get_issue_failed', detail: String(error?.message ?? error) } };
}

const issueLabels = normalizeLabels(issue?.labels || []);
const issueState = safeString(issue?.state);
const webUrl = safeString(issue?.web_url || req.issue_web_url || '');

if (!issueLabels.includes(cirLabel)) {
  return { json: { ...req, ok: true, skipped: true, reason: 'not_cir_issue', issue_state: issueState, issue_labels: issueLabels, issue_web_url: webUrl || null } };
}

const statusLabels = issueLabels.filter((l) => l.startsWith(statusPrefix));
const removeStatus = statusLabels.filter((l) => l !== closedLabel);

const needsClose = closeState && issueState !== 'closed';
const needsClosedLabel = !issueLabels.includes(closedLabel);
const needsUpdate = needsClose || needsClosedLabel || removeStatus.length > 0;

let updated = null;
let updateError = null;
if (needsUpdate) {
  const payload = {};
  if (needsClose) payload.state_event = 'close';
  const addLabels = [];
  if (needsClosedLabel) addLabels.push(closedLabel);
  if (addLabels.length) payload.add_labels = addLabels.join(',');
  if (removeStatus.length) payload.remove_labels = uniq(removeStatus).join(',');

  try {
    updated = await this.helpers.httpRequest({
      method: 'PUT',
      url: issueUrl,
      json: true,
      headers: { 'PRIVATE-TOKEN': token },
      body: payload,
      timeout: 8000,
    });
  } catch (error) {
    updateError = String(error?.message ?? error);
  }
}

if (updateError) {
  return { json: { ...req, ok: false, status_code: 502, error: 'gitlab_update_issue_failed', detail: updateError, issue_web_url: webUrl || null } };
}

let noteResult = { ok: true, skipped: true, reason: 'append_note_disabled' };
if (appendNote) {
  const marker = `<!-- itsm:cir:close:issue_id=${String(issue?.id ?? '')} status=${closedLabel} -->`;

  // list notes and search marker
  let notes = [];
  try {
    const notesUrl = `${issueUrl}/notes?per_page=100&sort=desc&order_by=updated_at`;
    const resp = await this.helpers.httpRequest({
      method: 'GET',
      url: notesUrl,
      json: true,
      headers: { 'PRIVATE-TOKEN': token },
      timeout: 8000,
    });
    notes = Array.isArray(resp) ? resp : (Array.isArray(resp?.data) ? resp.data : []);
  } catch (error) {
    // ignore; fallback to create note
    notes = [];
  }

  const hasMarker = notes.some((n) => String(n?.body ?? '').includes(marker));
  if (hasMarker && !forceNote) {
    noteResult = { ok: true, skipped: true, reason: 'note_already_exists', marker };
  } else {
    const noteBody = buildNoteBody({
      marker,
      target_app_root: req.target_app_root,
      operator: req.run_meta?.operator || null,
      run_id: req.run_meta?.run_id || null,
      status_label: closedLabel,
      issue_url: webUrl || null,
      usecase_ids: Array.isArray(req.usecase_ids) ? req.usecase_ids : [],
      result_summary: req.result_summary,
      verification: req.verification,
      artifacts: req.artifacts,
    });

    try {
      const noteUrl = `${issueUrl}/notes`;
      await this.helpers.httpRequest({
        method: 'POST',
        url: noteUrl,
        json: true,
        headers: { 'PRIVATE-TOKEN': token },
        body: { body: noteBody },
        timeout: 8000,
      });
      noteResult = { ok: true, skipped: false, marker };
    } catch (error) {
      noteResult = { ok: false, skipped: false, error: String(error?.message ?? error), marker };
    }
  }
}

return {
  json: {
    ...req,
    ok: noteResult.ok,
    status_code: noteResult.ok ? 200 : 207,
    issue_web_url: webUrl || null,
    before: {
      state: issueState,
      labels: issueLabels,
    },
    after: {
      state: safeString(updated?.state || (needsClose ? 'closed' : issueState)) || null,
      labels_added: needsClosedLabel ? [closedLabel] : [],
      labels_removed: removeStatus,
    },
    updated: Boolean(updated) || false,
    note: noteResult,
  }
};

const items = $input.all().map((it) => it.json ?? {});

const ok = items.every((r) => r.ok !== false);
const anyFailed = items.some((r) => r.ok === false);

const status = anyFailed ? 207 : 200;

return [{
  json: {
    ok,
    status_code: status,
    results: items,
    closed_count: items.filter((r) => r.updated).length,
    noted_count: items.filter((r) => r.note && r.note.ok && r.note.skipped === false).length,
    skipped_count: items.filter((r) => r.skipped).length,
  }
}];
